raw:
{
  "title": "赛博长安学府的剑影",
  "scene": "你是长安城赛博朋克学府的一名学生，期末考试即将来临，但你似乎遗失了最重要的复习资料。学府的一角，一个古老的石像下，你发现了一个神秘的包裹。旁边，机器猫正好奇地打量着你，似乎有意无意地挡住了包裹的一部分。你打开包裹，里面是一把会说话的剑，剑尖微微发光，轻声说：‘不是所有光芒都是智慧的指引……’。此时，一位学府的老师走过来，询问你是否找到了遗失的资料。她的眼神显得非常急切。",
  "goal": "找到复习资料，准备期末考试。",
  "clue": "机器猫挡住了包裹的一部分，暗示包裹内可能有陷阱；剑的暗示说明光芒（即看起来合理的东西）不一定是正确的。",
  "choices": [
    {
      "id": "A",
      "text": "检查包裹内的其他物品",
      "outcome": "你仔细检查包裹，发现了一些隐藏的笔记，这些笔记正是你遗失的复习资料。虽然过程稍显曲折，但你最终找到了需要的东西，准备迎接期末考试。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "直接把剑交给老师",
      "outcome": "老师接过剑，脸上露出了满意的笑容，但剑突然发出一声尖锐的警告，原来剑内藏有重要的复习资料。虽然你失去了剑，但老师奖励了你一本珍稀的参考书。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "告诉老师包裹内的光芒",
      "outcome": "老师听后显得更加急切，催促你快点把剑拿出来。你刚一拿出来，剑突然发出强烈的光芒，将你和老师都吓了一跳。包裹内并没有复习资料，反而是一些无用的杂物。老师失望地离开了，你只能重新寻找资料。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
